for name,description in worlds.items():
    jobs.append(dict(Id='World.'+name,File='world-references/'+name+'.png',Size=None,References=[],Prompt='Use case: stylized-concept. Orthographic three-quarter Roblox voxel toy model reference, isolated on light grey background. Build everything visibly from crisp cuboid blocks, bright flat colours and near-black edges. '+description+' Physical geometry only, no bitmap artwork on faces. Show the entire object with padding.'))
for name,description in screens.items():
    for device,size in [('Desktop',[1920,1080]),('Phone',[2400,1080])]:
        prompt=kit+f' Output canvas {size[0]}x{size[1]}, {device.lower()} landscape. '+('Large desktop layout with balanced margins. ' if device=='Desktop' else 'Mobile landscape: big 44px-or-larger touch targets, compact text, safe left/right edge margins and bottom corner control exclusions; responsive layout, not a stretched desktop screen. ')+description
        jobs.append(dict(Id='Mockups.'+name+'.'+device,File='mockups/'+name+'-'+device.lower()+'.png',Size=size,References=refs,Prompt=prompt))
for job in jobs:(OUT/job['File']).parent.mkdir(parents=True,exist_ok=True)
(OUT/'jobs.json').write_text(json.dumps(dict(Workflow='Built-in ImageGen, one generated reference per world prop; one full-screen mockup per screen and device',Jobs=jobs),indent=2))
(OUT/'scope.json').write_text(json.dumps(dict(World='Replace all world panels/sign images with solid-colour voxel geometry; live values are text-only SurfaceGuis; preserve all interactive contracts and floating knife billboards',BossTitles='Original 16 PNGs remain design references only; new solid-colour voxel geometry must not use those textures in the world',UI='46 full-screen mockups covering 23 screen/state/tab layouts in desktop and phone landscape; 24 individual knife silhouettes; asset coverage must use the shared kit',ExistingArt='82 uploaded assets in assets/voxel-ui',Status='In progress'),indent=2))
print('Prepared',len(jobs),'generation jobs:',len(worlds),'world references and',len(screens)*2,'full-screen UI mockups')
